Column.value:
/*
 * Bulk migration of element/connector stereotypes and diagram Applied Metamodel views.
 *
 * Script type:
 * - JavaScript in Enterprise Architect
 *
 * CSV file location:
 * - next to the EA model file
 *
 * Example:
 * C:\Models\MyModel.qea
 * C:\Models\ea_stereotype_diagram_mapping.csv
 *
 * CSV format:
 *
 * kind;from;to
 * element;OldProfile::OldElementStereo;NewProfile::NewElementStereo
 * connector;OldProfile::OldConnectorStereo;NewProfile::NewConnectorStereo
 * diagram;OldProfile::OldAppliedMetamodel;NewProfile::NewAppliedMetamodel
 *
 * For diagrams, this script changes:
 * - diagram.StyleEx key MDGView
 *
 * It does NOT change:
 * - diagram.MetaType
 * - diagram.Type
 *
 * Supported kind values:
 * - element
 * - stereotype
 * - elementstereotype
 * - connector
 * - connectorstereotype
 * - diagram
 * - diagramtype
 * - appliedmetamodel
 * - applied_metamodel
 * - mdgview
 *
 * Safety:
 * - DRY_RUN = true  -> only log changes
 * - DRY_RUN = false -> write changes
 */

var CSV_FILE_NAME = "ea_stereotype_diagram_mapping.csv";
var DRY_RUN = true;
var SYNC_ELEMENT_TAGGED_VALUES = true;

var stats = {
    packages: 0,
    elements: 0,
    connectors: 0,
    diagrams: 0,
    elementChanged: 0,
    connectorChanged: 0,
    diagramViewChanged: 0,
    errors: 0
};

var processedElementIds = {};
var processedConnectorIds = {};

var mappings = {
    element: [],
    connector: [],
    diagramView: []
};

function main()
{
    try
    {
        Repository.EnsureOutputVisible("Script");

        Session.Output("=== EA CSV Mapping Migration started ===");
        Session.Output("CSV_FILE_NAME = " + CSV_FILE_NAME);
        Session.Output("DRY_RUN       = " + DRY_RUN);

        var csvPath = getCsvPathNextToModel(CSV_FILE_NAME);

        Session.Output("CSV_PATH      = " + csvPath);
        Session.Output("");

        loadMappings(csvPath);

        var selectedPackage = Repository.GetTreeSelectedPackage();

        if (selectedPackage == null)
        {
            Session.Output("[ERROR] Please select a package in the Project Browser.");
            return;
        }

        Session.Output("Selected package: " + selectedPackage.Name);
        Session.Output("");

        processPackage(selectedPackage);

        if (!DRY_RUN)
        {
            Repository.RefreshModelView(selectedPackage.PackageID);
        }

        Session.Output("");
        Session.Output("=== Summary ===");
        Session.Output("Packages scanned:                  " + stats.packages);
        Session.Output("Elements scanned:                  " + stats.elements);
        Session.Output("Connectors scanned:                " + stats.connectors);
        Session.Output("Diagrams scanned:                  " + stats.diagrams);
        Session.Output("Element stereotype changes:        " + stats.elementChanged);
        Session.Output("Connector stereotype changes:      " + stats.connectorChanged);
        Session.Output("Applied Metamodel changes:         " + stats.diagramViewChanged);
        Session.Output("Errors:                            " + stats.errors);

        if (DRY_RUN)
        {
            Session.Output("");
            Session.Output("DRY_RUN is active. No changes were written.");
            Session.Output("Set DRY_RUN = false to write the detected changes.");
        }

        Session.Output("=== EA CSV Mapping Migration finished ===");
    }
    catch (e)
    {
        Session.Output("[FATAL] " + getErrorText(e));
    }
}

function getCsvPathNextToModel(fileName)
{
    var fso = new COMObject("Scripting.FileSystemObject");
    var modelPath = Repository.ConnectionString;

    if (modelPath == null || trim(modelPath) == "")
    {
        throw new Error("Model path could not be determined from Repository.ConnectionString.");
    }

    if (!fso.FileExists(modelPath))
    {
        throw new Error(
            "Repository.ConnectionString is not a model file path. " +
            "This script expects a file-based EA model, for example .eap, .eapx, .qea or .qeax. " +
            "ConnectionString was: " + modelPath
        );
    }

    var modelFolder = fso.GetParentFolderName(modelPath);
    var csvPath = fso.BuildPath(modelFolder, fileName);

    if (!fso.FileExists(csvPath))
    {
        throw new Error("CSV mapping file not found next to model: " + csvPath);
    }

    return csvPath;
}

function loadMappings(csvPath)
{
    var fso = new COMObject("Scripting.FileSystemObject");

    if (!fso.FileExists(csvPath))
    {
        throw new Error("CSV file not found: " + csvPath);
    }

    var file = fso.OpenTextFile(csvPath, 1, false);
    var text = file.ReadAll();
    file.Close();

    text = removeBom(text);

    var lines = text.split(/\r\n|\n|\r/);
    var delimiter = detectDelimiter(lines);
    var headerFound = false;

    for (var i = 0; i < lines.length; i++)
    {
        var line = trim(lines[i]);

        if (line == "" || startsWith(line, "#") || startsWith(line, "//"))
        {
            continue;
        }

        var fields = parseCsvLine(line, delimiter);

        if (fields.length < 3)
        {
            Session.Output("[WARN] Ignored CSV line " + (i + 1) + ": expected at least 3 columns.");
            continue;
        }

        var rawKind = trim(fields[0]);
        var kind = normalizeKind(rawKind);
        var fromValue = trim(fields[1]);
        var toValue = trim(fields[2]);

        if (!headerFound && lower(rawKind) == "kind")
        {
            headerFound = true;
            continue;
        }

        headerFound = true;

        if (fromValue == "" || toValue == "")
        {
            Session.Output("[WARN] Ignored CSV line " + (i + 1) + ": empty from/to value.");
            continue;
        }

        if (kind == "element")
        {
            mappings.element.push({
                fromValue: fromValue,
                toValue: toValue
            });
        }
        else if (kind == "connector")
        {
            mappings.connector.push({
                fromValue: fromValue,
                toValue: toValue
            });
        }
        else if (kind == "diagramView")
        {
            mappings.diagramView.push({
                fromValue: fromValue,
                toValue: toValue
            });
        }
        else
        {
            Session.Output("[WARN] Ignored CSV line " + (i + 1) + ": unknown kind '" + rawKind + "'.");
        }
    }

    Session.Output("Mappings loaded:");
    Session.Output("- element:          " + mappings.element.length);
    Session.Output("- connector:        " + mappings.connector.length);
    Session.Output("- applied metamodel:" + mappings.diagramView.length);
    Session.Output("");
}

function processPackage(pkg)
{
    stats.packages++;

    processPackageElement(pkg);
    processDiagramCollection(pkg.Diagrams, "Package '" + pkg.Name + "'");

    for (var i = 0; i < pkg.Elements.Count; i++)
    {
        processElement(pkg.Elements.GetAt(i));
    }

    for (var j = 0; j < pkg.Packages.Count; j++)
    {
        processPackage(pkg.Packages.GetAt(j));
    }
}

function processPackageElement(pkg)
{
    try
    {
        var packageElement = pkg.Element;

        if (packageElement != null)
        {
            processElementWithoutRecursingIntoChildren(packageElement);
        }
    }
    catch (e)
    {
        // Package element could not be accessed. Package diagrams and child content are still processed.
    }
}

function processElement(element)
{
    if (element == null)
    {
        return;
    }

    var key = "" + element.ElementID;

    if (processedElementIds[key])
    {
        return;
    }

    processedElementIds[key] = true;
    stats.elements++;

    changeElementStereotype(element);
    processDiagramCollection(element.Diagrams, "Element '" + element.Name + "'");
    processConnectorCollection(element.Connectors);

    for (var i = 0; i < element.Elements.Count; i++)
    {
        processElement(element.Elements.GetAt(i));
    }

    for (var j = 0; j < element.EmbeddedElements.Count; j++)
    {
        processElement(element.EmbeddedElements.GetAt(j));
    }
}

function processElementWithoutRecursingIntoChildren(element)
{
    if (element == null)
    {
        return;
    }

    var key = "" + element.ElementID;

    if (processedElementIds[key])
    {
        return;
    }

    processedElementIds[key] = true;
    stats.elements++;

    changeElementStereotype(element);
    processDiagramCollection(element.Diagrams, "Element '" + element.Name + "'");
    processConnectorCollection(element.Connectors);
}

function processConnectorCollection(connectors)
{
    if (connectors == null)
    {
        return;
    }

    for (var i = 0; i < connectors.Count; i++)
    {
        var connector = connectors.GetAt(i);
        var key = "" + connector.ConnectorID;

        if (processedConnectorIds[key])
        {
            continue;
        }

        processedConnectorIds[key] = true;
        stats.connectors++;

        changeConnectorStereotype(connector);
    }
}

function processDiagramCollection(diagrams, ownerText)
{
    if (diagrams == null)
    {
        return;
    }

    for (var i = 0; i < diagrams.Count; i++)
    {
        var diagram = diagrams.GetAt(i);
        stats.diagrams++;

        changeDiagramAppliedMetamodel(diagram, ownerText);
    }
}

function changeElementStereotype(element)
{
    if (mappings.element.length == 0)
    {
        return;
    }

    var current = safeString(element.StereotypeEx);
    var newValue = current;
    var changed = false;

    for (var i = 0; i < mappings.element.length; i++)
    {
        var mapping = mappings.element[i];

        if (elementHasStereotype(element, mapping.fromValue))
        {
            newValue = replaceStereotypeInList(newValue, mapping.fromValue, mapping.toValue);
            changed = true;
        }
    }

    if (!changed)
    {
        return;
    }

    stats.elementChanged++;

    logChange(
        "ELEMENT",
        element.Name,
        element.ElementGUID,
        current,
        newValue
    );

    if (DRY_RUN)
    {
        return;
    }

    element.StereotypeEx = newValue;

    if (!element.Update())
    {
        stats.errors++;
        Session.Output("[ERROR] Element update failed: " + element.Name + " / " + element.GetLastError());
        return;
    }

    if (SYNC_ELEMENT_TAGGED_VALUES)
    {
        syncElementTagsForMappings(element, mappings.element);
    }

    element.Refresh();
}

function changeConnectorStereotype(connector)
{
    if (mappings.connector.length == 0)
    {
        return;
    }

    var current = safeString(connector.StereotypeEx);
    var newValue = current;
    var changed = false;

    for (var i = 0; i < mappings.connector.length; i++)
    {
        var mapping = mappings.connector[i];

        if (stereotypeListContains(current, mapping.fromValue))
        {
            newValue = replaceStereotypeInList(newValue, mapping.fromValue, mapping.toValue);
            changed = true;
        }
    }

    if (!changed)
    {
        return;
    }

    stats.connectorChanged++;

    logChange(
        "CONNECTOR",
        connector.Name + " [" + connector.Type + "]",
        connector.ConnectorGUID,
        current,
        newValue
    );

    if (DRY_RUN)
    {
        return;
    }

    connector.StereotypeEx = newValue;

    if (!connector.Update())
    {
        stats.errors++;
        Session.Output("[ERROR] Connector update failed: " + connector.Name + " / " + connector.GetLastError());
        return;
    }
}

function changeDiagramAppliedMetamodel(diagram, ownerText)
{
    if (mappings.diagramView.length == 0)
    {
        return;
    }

    var styleEx = safeString(diagram.StyleEx);
    var currentView = getStyleExValue(styleEx, "MDGView");

    for (var i = 0; i < mappings.diagramView.length; i++)
    {
        var mapping = mappings.diagramView[i];

        if (sameNameOrLocalName(currentView, mapping.fromValue))
        {
            var newStyleEx = setStyleExValue(styleEx, "MDGView", mapping.toValue);

            stats.diagramViewChanged++;

            logChange(
                "DIAGRAM_APPLIED_METAMODEL",
                ownerText + " / " + diagram.Name,
                diagram.DiagramGUID,
                currentView,
                mapping.toValue
            );

            Session.Output(
                "    StyleEx: '" +
                styleEx +
                "' -> '" +
                newStyleEx +
                "'"
            );

            if (DRY_RUN)
            {
                return;
            }

            diagram.StyleEx = newStyleEx;

            if (!diagram.Update())
            {
                stats.errors++;
                Session.Output("[ERROR] Diagram update failed: " + diagram.Name + " / " + diagram.GetLastError());
                return;
            }

            Repository.ReloadDiagram(diagram.DiagramID);
            return;
        }
    }
}

function getStyleExValue(styleEx, key)
{
    var entries = splitStyleEx(styleEx);
    var normalizedKey = lower(trim(key));

    for (var i = 0; i < entries.length; i++)
    {
        var entry = entries[i];
        var idx = entry.indexOf("=");

        if (idx < 0)
        {
            continue;
        }

        var entryKey = trim(entry.substring(0, idx));
        var entryValue = trim(entry.substring(idx + 1));

        if (lower(entryKey) == normalizedKey)
        {
            return entryValue;
        }
    }

    return "";
}

function setStyleExValue(styleEx, key, value)
{
    var entries = splitStyleEx(styleEx);
    var normalizedKey = lower(trim(key));
    var result = [];
    var written = false;

    for (var i = 0; i < entries.length; i++)
    {
        var entry = trim(entries[i]);

        if (entry == "")
        {
            continue;
        }

        var idx = entry.indexOf("=");

        if (idx < 0)
        {
            result.push(entry);
            continue;
        }

        var entryKey = trim(entry.substring(0, idx));

        if (lower(entryKey) == normalizedKey)
        {
            result.push(key + "=" + value);
            written = true;
        }
        else
        {
            result.push(entry);
        }
    }

    if (!written)
    {
        result.push(key + "=" + value);
    }

    return result.join(";") + ";";
}

function splitStyleEx(styleEx)
{
    styleEx = safeString(styleEx);

    if (styleEx == "")
    {
        return [];
    }

    return styleEx.split(";");
}

function syncElementTagsForMappings(element, elementMappings)
{
    for (var i = 0; i < elementMappings.length; i++)
    {
        var mapping = elementMappings[i];

        if (elementHasStereotype(element, mapping.toValue))
        {
            var profile = getProfileName(mapping.toValue);
            var stereotype = getLocalName(mapping.toValue);

            if (profile != "")
            {
                try
                {
                    element.SynchTaggedValues(profile, stereotype);
                }
                catch (e)
                {
                    stats.errors++;
                    Session.Output(
                        "[WARN] Tagged value sync failed for element '" +
                        element.Name +
                        "' with stereotype '" +
                        mapping.toValue +
                        "': " +
                        getErrorText(e)
                    );
                }
            }
        }
    }
}

function replaceStereotypeInList(currentList, fromStereo, toStereo)
{
    var parts = splitStereoList(currentList);
    var result = [];
    var replaced = false;

    for (var i = 0; i < parts.length; i++)
    {
        var current = trim(parts[i]);

        if (current == "")
        {
            continue;
        }

        if (sameNameOrLocalName(current, fromStereo))
        {
            if (!arrayContainsStereo(result, toStereo))
            {
                result.push(toStereo);
            }

            replaced = true;
        }
        else
        {
            if (!arrayContainsStereo(result, current))
            {
                result.push(current);
            }
        }
    }

    if (!replaced)
    {
        result.push(toStereo);
    }

    return result.join(",");
}

function elementHasStereotype(element, stereotypeName)
{
    try
    {
        if (element.HasStereotype(stereotypeName))
        {
            return true;
        }
    }
    catch (e)
    {
        // Fallback below.
    }

    return stereotypeListContains(element.StereotypeEx, stereotypeName);
}

function stereotypeListContains(currentList, stereotypeName)
{
    var parts = splitStereoList(currentList);

    for (var i = 0; i < parts.length; i++)
    {
        if (sameNameOrLocalName(parts[i], stereotypeName))
        {
            return true;
        }
    }

    return false;
}

function splitStereoList(value)
{
    value = safeString(value);

    if (value == "")
    {
        return [];
    }

    return value.split(",");
}

function sameNameOrLocalName(a, b)
{
    a = trim(a);
    b = trim(b);

    if (lower(a) == lower(b))
    {
        return true;
    }

    if (lower(getLocalName(a)) == lower(getLocalName(b)))
    {
        return true;
    }

    return false;
}

function arrayContainsStereo(array, stereotypeName)
{
    for (var i = 0; i < array.length; i++)
    {
        if (sameNameOrLocalName(array[i], stereotypeName))
        {
            return true;
        }
    }

    return false;
}

function getProfileName(qualifiedName)
{
    qualifiedName = trim(qualifiedName);

    var idx = qualifiedName.indexOf("::");

    if (idx < 0)
    {
        return "";
    }

    return qualifiedName.substring(0, idx);
}

function getLocalName(qualifiedName)
{
    qualifiedName = trim(qualifiedName);

    var idx = qualifiedName.lastIndexOf("::");

    if (idx < 0)
    {
        return qualifiedName;
    }

    return trim(qualifiedName.substring(idx + 2));
}

function normalizeKind(kind)
{
    kind = lower(trim(kind));

    if (
        kind == "stereotype" ||
        kind == "elementstereotype" ||
        kind == "element_stereotype" ||
        kind == "element"
    )
    {
        return "element";
    }

    if (
        kind == "connectorstereotype" ||
        kind == "connector_stereotype" ||
        kind == "connector"
    )
    {
        return "connector";
    }

    if (
        kind == "diagram" ||
        kind == "diagramtype" ||
        kind == "diagram_type" ||
        kind == "appliedmetamodel" ||
        kind == "applied_metamodel" ||
        kind == "mdgview"
    )
    {
        return "diagramView";
    }

    return kind;
}

function detectDelimiter(lines)
{
    for (var i = 0; i < lines.length; i++)
    {
        var line = trim(lines[i]);

        if (line == "" || startsWith(line, "#") || startsWith(line, "//"))
        {
            continue;
        }

        var semicolonCount = countCharOutsideQuotes(line, ";");
        var commaCount = countCharOutsideQuotes(line, ",");

        if (semicolonCount >= commaCount)
        {
            return ";";
        }

        return ",";
    }

    return ";";
}

function parseCsvLine(line, delimiter)
{
    var result = [];
    var current = "";
    var inQuotes = false;

    for (var i = 0; i < line.length; i++)
    {
        var ch = line.charAt(i);

        if (ch == '"')
        {
            if (inQuotes && i + 1 < line.length && line.charAt(i + 1) == '"')
            {
                current += '"';
                i++;
            }
            else
            {
                inQuotes = !inQuotes;
            }
        }
        else if (ch == delimiter && !inQuotes)
        {
            result.push(trim(current));
            current = "";
        }
        else
        {
            current += ch;
        }
    }

    result.push(trim(current));

    return result;
}

function countCharOutsideQuotes(line, ch)
{
    var count = 0;
    var inQuotes = false;

    for (var i = 0; i < line.length; i++)
    {
        var current = line.charAt(i);

        if (current == '"')
        {
            inQuotes = !inQuotes;
        }
        else if (current == ch && !inQuotes)
        {
            count++;
        }
    }

    return count;
}

function logChange(kind, name, guid, fromValue, toValue)
{
    Session.Output(
        "[" + kind + "] " +
        name +
        " | " +
        guid +
        " | '" +
        fromValue +
        "' -> '" +
        toValue +
        "'"
    );
}

function getErrorText(e)
{
    if (e == null)
    {
        return "";
    }

    if (e.description != null)
    {
        return e.description;
    }

    if (e.message != null)
    {
        return e.message;
    }

    return "" + e;
}

function safeString(value)
{
    if (value == null)
    {
        return "";
    }

    return "" + value;
}

function trim(value)
{
    return safeString(value).replace(/^\s+|\s+$/g, "");
}

function lower(value)
{
    return safeString(value).toLowerCase();
}

function startsWith(value, prefix)
{
    return value.substring(0, prefix.length) == prefix;
}

function removeBom(value)
{
    if (value.length > 0 && value.charCodeAt(0) == 0xFEFF)
    {
        return value.substring(1);
    }

    return value;
}

main();

/*
 * SAF_Mapping_Base v3
 *
 * Supported migrations:
 * - Package names
 * - Element stereotypes
 * - Connector stereotypes
 * - Diagram Applied Metamodel / Viewpoint through StyleEx key MDGView
 *
 * Supported modes:
 * - DRY_RUN
 * - APPLY
 * - ROLLBACK
 *
 * Mapping files beside the EA model:
 * - DefaultMapping.csv (required)
 * - ProjectMapping.csv (optional, overrides matching default mappings)
 *
 * CSV format:
 * kind;from;to
 * package;OldPackageName;NewPackageName
 * element;OldStereotype;NewStereotype
 * connector;OldConnectorStereotype;NewConnectorStereotype
 * diagram;OldViewpoint;NewViewpoint
 *
 * Generated files:
 * - ea_stereotype_diagram_mapping.dryrun.txt
 * - ea_stereotype_diagram_mapping.rollback.csv
 *
 * Apply strategy:
 * 1. Discover the complete immutable change plan without changing the model.
 * 2. Write one rollback row for every planned change and close the file.
 * 3. Apply the stored plan by GUID.
 * 4. Verify every final value semantically.
 *
 * This prevents parent updates from changing the discovery result for children.
 */

!INC Local Scripts.EAConstants-JavaScript

var SAF_MAPPING_MODE_DRY_RUN = "DRY_RUN";
var SAF_MAPPING_MODE_APPLY = "APPLY";
var SAF_MAPPING_MODE_ROLLBACK = "ROLLBACK";

var SAF_DEFAULT_MAPPING_FILE_NAME = "DefaultMapping.csv";
var SAF_PROJECT_MAPPING_FILE_NAME = "ProjectMapping.csv";
var SAF_DRY_RUN_REPORT_FILE_NAME = "ea_stereotype_diagram_mapping.dryrun.txt";
var SAF_ROLLBACK_FILE_NAME = "ea_stereotype_diagram_mapping.rollback.csv";
var SAF_MAPPING_SYNC_ELEMENT_TAGGED_VALUES = true;
var SAF_MAPPING_CSV_DELIMITER = ";";

var safMappingMode = "";
var safMappings = null;
var safStats = null;
var safContext = null;

var safProcessedElementIds = {};
var safProcessedConnectorIds = {};
var safProcessedPackageIds = {};
var safProcessedDiagramIds = {};

var safPlannedChanges = [];
var safPlannedChangeKeys = {};

var safDryRunReportWriter = null;
var safDryRunReportPath = "";
var safDryRunHierarchyNodes = [];
var safDryRunHierarchyStack = [];

var safRollbackWriter = null;
var safRollbackPath = "";
var safRollbackIssues = [];
var safApplyIssues = [];

var safPendingApplyVerifications = [];
var safPendingRollbackVerifications = [];

function SAFMapping_Run(mode) {
    safMappingMode = mode;

    try {
        SAFMapping_InitRun();

        if (mode == SAF_MAPPING_MODE_ROLLBACK) {
            SAFMapping_RunRollback();
        } else if (mode == SAF_MAPPING_MODE_DRY_RUN || mode == SAF_MAPPING_MODE_APPLY) {
            SAFMapping_RunForward(mode);
        } else {
            throw new Error("Unsupported SAF Mapping mode: " + mode);
        }

        SAFMapping_WriteSummary();
    } catch (e) {
        if (safStats != null) {
            safStats.errors++;
        }

        SAFMapping_Output("[FATAL] " + SAFMapping_GetErrorText(e));
        SAFMapping_WriteDryRunText("[FATAL] " + SAFMapping_GetErrorText(e));
    } finally {
        SAFMapping_CloseDryRunReportWriter();
        SAFMapping_CloseRollbackWriter();
    }
}

function SAFMapping_InitRun() {
    Repository.EnsureOutputVisible("Script");

    safMappings = {
        packageName: [],
        element: [],
        connector: [],
        diagramView: []
    };

    safStats = {
        packages: 0,
        elements: 0,
        connectors: 0,
        diagrams: 0,

        packageDetected: 0,
        elementDetected: 0,
        connectorDetected: 0,
        diagramViewDetected: 0,
        plannedChanges: 0,

        packageWritten: 0,
        elementWritten: 0,
        connectorWritten: 0,
        diagramViewWritten: 0,

        defaultMappingsLoaded: 0,
        projectMappingsLoaded: 0,
        projectMappingsOverridden: 0,

        rollbackRowsRead: 0,
        rollbackRowsWritten: 0,
        rollbackRowsApplied: 0,
        rollbackRowsAlreadyRestored: 0,
        rollbackRowsRestored: 0,
        rollbackRowsSkipped: 0,

        rollbackPackagesMissing: 0,
        rollbackElementsMissing: 0,
        rollbackConnectorsMissing: 0,
        rollbackDiagramsMissing: 0,
        rollbackValueMismatches: 0,
        rollbackVerificationFailures: 0,
		rollbackPendingVerifications: 0,
		rollbackVerifiedInFinalPass: 0,

        applyExplicitUpdates: 0,
        applyAlreadyTarget: 0,
        applyTargetVerified: 0,
        applyConflicts: 0,
        applyObjectsMissing: 0,
        applyUpdateFailures: 0,
        applyVerificationFailures: 0,
		applyPendingVerifications: 0,
		applyVerifiedInFinalPass: 0,

        errors: 0
    };

    safContext = null;
    safProcessedElementIds = {};
    safProcessedConnectorIds = {};
    safProcessedPackageIds = {};
    safProcessedDiagramIds = {};
    safPlannedChanges = [];
    safPlannedChangeKeys = {};
	safPendingApplyVerifications = [];
	safPendingRollbackVerifications = [];

    safDryRunReportWriter = null;
    safDryRunReportPath = "";
    safDryRunHierarchyNodes = [];
    safDryRunHierarchyStack = [];

    safRollbackWriter = null;
    safRollbackPath = "";
    safRollbackIssues = [];
    safApplyIssues = [];

    SAFMapping_Output("=== SAF Mapping Migration started ===");
    SAFMapping_Output("Mode: " + safMappingMode);
}

function SAFMapping_RunForward(mode) {
    var defaultMappingPath = SAFMapping_GetRequiredPathNextToModel(SAF_DEFAULT_MAPPING_FILE_NAME);
    var projectMappingPath = SAFMapping_GetOptionalPathNextToModel(SAF_PROJECT_MAPPING_FILE_NAME);

    SAFMapping_Output("Default mapping file: " + defaultMappingPath);
    SAFMapping_LoadMappings(defaultMappingPath, "DEFAULT");

    if (projectMappingPath != "") {
        SAFMapping_Output("Project mapping file: " + projectMappingPath);
        SAFMapping_LoadMappings(projectMappingPath, "PROJECT");
    } else {
        SAFMapping_Output("Project mapping file: not found, continuing without project mappings.");
    }

    SAFMapping_Output("");
    SAFMapping_Output("Effective mappings:");
    SAFMapping_Output("- package names:         " + safMappings.packageName.length);
    SAFMapping_Output("- element stereotypes:   " + safMappings.element.length);
    SAFMapping_Output("- connector stereotypes: " + safMappings.connector.length);
    SAFMapping_Output("- diagram viewpoints:    " + safMappings.diagramView.length);

    if (mode == SAF_MAPPING_MODE_DRY_RUN) {
        safDryRunReportPath = SAFMapping_GetPathNextToModelWithoutExistenceCheck(SAF_DRY_RUN_REPORT_FILE_NAME);
        SAFMapping_OpenDryRunReportWriter(safDryRunReportPath, defaultMappingPath, projectMappingPath);
        SAFMapping_Output("Dry Run report file: " + safDryRunReportPath);
    }

    SAFMapping_Output("");
    safContext = SAFMapping_DiscoverCurrentProjectBrowserContext();
    safStats.plannedChanges = safPlannedChanges.length;

    SAFMapping_Output("");
    SAFMapping_Output("Immutable change plan created: " + safPlannedChanges.length + " changes.");

    if (mode == SAF_MAPPING_MODE_APPLY) {
        safRollbackPath = SAFMapping_GetPathNextToModelWithoutExistenceCheck(SAF_ROLLBACK_FILE_NAME);
        SAFMapping_OpenRollbackWriter(safRollbackPath);
        SAFMapping_WriteCompleteRollbackSnapshot();
        SAFMapping_CloseRollbackWriter();

        if (safStats.rollbackRowsWritten != safPlannedChanges.length) {
            throw new Error(
                "Rollback snapshot incomplete. Apply aborted before model changes. Planned: " +
                safPlannedChanges.length + ", rollback rows: " + safStats.rollbackRowsWritten + ".");
        }

        SAFMapping_Output("Rollback snapshot written and closed: " + safRollbackPath);
        SAFMapping_Output("");
        SAFMapping_ApplyPlannedChanges();
		SAFMapping_RefreshContextAfterApply();
		SAFMapping_FinalizePendingApplyVerifications();
    }
}

function SAFMapping_RunRollback() {
    var rollbackPath = SAFMapping_GetRequiredPathNextToModel(SAF_ROLLBACK_FILE_NAME);

    SAFMapping_Output("Rollback file: " + rollbackPath);
    SAFMapping_Output("");

    SAFMapping_ApplyRollbackFile(rollbackPath);
    SAFMapping_FinalizePendingRollbackVerifications();
}

function SAFMapping_DiscoverCurrentProjectBrowserContext() {
    var selectedType = Repository.GetTreeSelectedItemType();
    var selectedObject = Repository.GetTreeSelectedObject();

    if (selectedObject == null) {
        throw new Error("No Project Browser object selected.");
    }

    if (selectedType == otPackage) {
        SAFMapping_Output("Context package: " + selectedObject.Name);
        SAFMapping_WriteDryRunText("Context: Package \"" + selectedObject.Name + "\"");
        SAFMapping_WriteDryRunText("");
        SAFMapping_ProcessPackage(selectedObject, 0);
        return { type: "package", packageId: selectedObject.PackageID };
    }

    if (selectedType == otElement) {
        SAFMapping_Output("Context element: " + selectedObject.Name);
        SAFMapping_WriteDryRunText("Context: Element \"" + selectedObject.Name + "\"");
        SAFMapping_WriteDryRunText("");
        SAFMapping_ProcessElement(selectedObject, 0);
        return { type: "element", packageId: selectedObject.PackageID };
    }

    if (selectedType == otDiagram) {
        SAFMapping_Output("Context diagram: " + selectedObject.Name);
        SAFMapping_WriteDryRunText("Context: Diagram \"" + selectedObject.Name + "\"");
        SAFMapping_WriteDryRunText("");
        SAFMapping_ProcessDiagram(selectedObject, 0);
        return { type: "diagram", diagramId: selectedObject.DiagramID };
    }

    throw new Error(
        "Unsupported Project Browser object type: " + selectedType +
        ". Select a package, element or diagram.");
}

function SAFMapping_RefreshContextAfterApply() {
    if (safContext == null) {
        return;
    }

    if ((safContext.type == "package" || safContext.type == "element") && safContext.packageId > 0) {
        Repository.RefreshModelView(safContext.packageId);
    }

    if (safContext.type == "diagram" && safContext.diagramId > 0) {
        Repository.ReloadDiagram(safContext.diagramId);
    }
}

function SAFMapping_LoadMappings(csvPath, sourceType) {
    var fso = new COMObject("Scripting.FileSystemObject");
    var file = fso.OpenTextFile(csvPath, 1, false);
    var text = file.ReadAll();
    file.Close();

    text = SAFMapping_RemoveBom(text);
    var rows = SAFMapping_ParseCsvText(text, SAFMapping_DetectDelimiterFromText(text));
    var headerProcessed = false;

    for (var i = 0; i < rows.length; i++) {
        var fields = rows[i];

        if (fields == null || fields.length == 0) {
            continue;
        }

        if (fields.length == 1 && SAFMapping_Trim(fields[0]) == "") {
            continue;
        }

        var rawKind = SAFMapping_Trim(fields[0]);

        if (rawKind == "" || SAFMapping_StartsWith(rawKind, "#") || SAFMapping_StartsWith(rawKind, "//")) {
            continue;
        }

        if (!headerProcessed && SAFMapping_Lower(rawKind) == "kind") {
            headerProcessed = true;
            continue;
        }

        headerProcessed = true;

        if (fields.length < 3) {
            SAFMapping_Output(
                "[WARN] Ignored mapping row " + (i + 1) + " in " + csvPath +
                ": expected at least 3 columns.");
            continue;
        }

        var kind = SAFMapping_NormalizeKind(rawKind);
        var fromValue = SAFMapping_Trim(fields[1]);
        var toValue = SAFMapping_Trim(fields[2]);

        if (fromValue == "" || toValue == "") {
            SAFMapping_Output(
                "[WARN] Ignored mapping row " + (i + 1) + " in " + csvPath +
                ": empty from/to value.");
            continue;
        }

        if (SAFMapping_SameText(fromValue, toValue)) {
            continue;
        }

        if (kind != "packageName" && kind != "element" && kind != "connector" && kind != "diagramView") {
            SAFMapping_Output(
                "[WARN] Ignored mapping row " + (i + 1) + " in " + csvPath +
                ": unknown kind '" + rawKind + "'.");
            continue;
        }

        SAFMapping_AddOrReplaceMapping(kind, fromValue, toValue, sourceType);
    }
}
function SAFMapping_AddOrReplaceMapping(kind, fromValue, toValue, sourceType) {
    var targetCollection = SAFMapping_GetMappingCollection(kind);
    var existingIndex = SAFMapping_FindMappingIndex(targetCollection, fromValue);
    var entry = { fromValue: fromValue, toValue: toValue, sourceType: sourceType };

    if (existingIndex >= 0) {
        if (sourceType == "PROJECT") {
            var oldEntry = targetCollection[existingIndex];
            SAFMapping_Output(
                "[PROJECT OVERRIDE] " + SAFMapping_GetDisplayKind(kind) + " | " +
                oldEntry.fromValue + " | " + oldEntry.toValue + " --> " + toValue);
            targetCollection[existingIndex] = entry;
            safStats.projectMappingsOverridden++;
        } else {
            SAFMapping_Output(
                "[WARN] Duplicate default mapping ignored: " + SAFMapping_GetDisplayKind(kind) +
                " | " + fromValue + " --> " + toValue);
        }
        return;
    }

    targetCollection.push(entry);

    if (sourceType == "PROJECT") {
        safStats.projectMappingsLoaded++;
    } else {
        safStats.defaultMappingsLoaded++;
    }
}

function SAFMapping_GetMappingCollection(kind) {
    if (kind == "packageName") {
        return safMappings.packageName;
    }
    if (kind == "element") {
        return safMappings.element;
    }
    if (kind == "connector") {
        return safMappings.connector;
    }
    if (kind == "diagramView") {
        return safMappings.diagramView;
    }
    throw new Error("Unsupported mapping kind: " + kind);
}

function SAFMapping_FindMappingIndex(collection, fromValue) {
    for (var i = 0; i < collection.length; i++) {
        if (SAFMapping_SameNameOrLocalName(collection[i].fromValue, fromValue)) {
            return i;
        }
    }
    return -1;
}

function SAFMapping_GetDisplayKind(kind) {
    if (kind == "packageName" || kind == "package") {
        return "PACKAGE";
    }
    if (kind == "element") {
        return "ELEMENT";
    }
    if (kind == "connector") {
        return "CONNECTOR";
    }
    if (kind == "diagramView") {
        return "DIAGRAM";
    }
    return kind;
}

function SAFMapping_ProcessPackage(pkg, depth) {
    if (pkg == null) {
        return;
    }
    if (depth == null) {
        depth = 0;
    }

    var packageKey = "" + pkg.PackageID;
    if (safProcessedPackageIds[packageKey]) {
        return;
    }
    safProcessedPackageIds[packageKey] = true;
    safStats.packages++;

    SAFMapping_WriteDryRunHierarchyObject(
        depth,
        "Package",
        SAFMapping_SafeName(pkg.Name, "<unnamed package>"));

    SAFMapping_ChangePackageName(pkg, depth);
    SAFMapping_ProcessPackageElement(pkg, depth + 1);
    SAFMapping_ProcessDiagramArray(SAFMapping_GetSortedCollection(pkg.Diagrams), depth + 1);

    var elements = SAFMapping_GetSortedCollection(pkg.Elements);
    for (var i = 0; i < elements.length; i++) {
        SAFMapping_ProcessElement(elements[i], depth + 1);
    }

    var packages = SAFMapping_GetSortedCollection(pkg.Packages);
    for (var j = 0; j < packages.length; j++) {
        SAFMapping_ProcessPackage(packages[j], depth + 1);
    }
}

function SAFMapping_ProcessPackageElement(pkg, depth) {
    try {
        var packageElement = pkg.Element;
        if (packageElement != null) {
            SAFMapping_ProcessElementWithoutChildren(packageElement, depth);
        }
    } catch (e) {
        SAFMapping_Output(
            "[WARN] Package element could not be processed for package '" + pkg.Name +
            "': " + SAFMapping_GetErrorText(e));
    }
}

function SAFMapping_ProcessElement(element, depth) {
    if (element == null) {
        return;
    }
    if (depth == null) {
        depth = 0;
    }

    var elementKey = "" + element.ElementID;
    if (safProcessedElementIds[elementKey]) {
        return;
    }
    safProcessedElementIds[elementKey] = true;
    safStats.elements++;

    SAFMapping_WriteDryRunHierarchyObject(
        depth,
        "Element",
        SAFMapping_SafeName(element.Name, "<unnamed element>"));

    SAFMapping_ChangeElementStereotype(element, depth);
    SAFMapping_ProcessDiagramArray(SAFMapping_GetSortedCollection(element.Diagrams), depth + 1);
    SAFMapping_ProcessConnectorArray(SAFMapping_GetSortedCollection(element.Connectors), depth + 1);

    var children = SAFMapping_GetMergedSortedElementChildren(element);
    for (var i = 0; i < children.length; i++) {
        SAFMapping_ProcessElement(children[i], depth + 1);
    }
}

function SAFMapping_ProcessElementWithoutChildren(element, depth) {
    if (element == null) {
        return;
    }
    if (depth == null) {
        depth = 0;
    }

    var elementKey = "" + element.ElementID;
    if (safProcessedElementIds[elementKey]) {
        return;
    }
    safProcessedElementIds[elementKey] = true;
    safStats.elements++;

    SAFMapping_WriteDryRunHierarchyObject(
        depth,
        "Element",
        SAFMapping_SafeName(element.Name, "<unnamed element>"));

    SAFMapping_ChangeElementStereotype(element, depth);
    SAFMapping_ProcessDiagramArray(SAFMapping_GetSortedCollection(element.Diagrams), depth + 1);
    SAFMapping_ProcessConnectorArray(SAFMapping_GetSortedCollection(element.Connectors), depth + 1);
}

function SAFMapping_ProcessConnectorArray(connectors, depth) {
    for (var i = 0; i < connectors.length; i++) {
        var connector = connectors[i];
        var connectorKey = "" + connector.ConnectorID;

        if (safProcessedConnectorIds[connectorKey]) {
            continue;
        }

        safProcessedConnectorIds[connectorKey] = true;
        safStats.connectors++;

        var connectorName = SAFMapping_GetConnectorDisplayName(connector);
        SAFMapping_WriteDryRunHierarchyObject(depth, "Connector", connectorName);
        SAFMapping_ChangeConnectorStereotype(connector, depth);
    }
}

function SAFMapping_ProcessDiagramArray(diagrams, depth) {
    for (var i = 0; i < diagrams.length; i++) {
        SAFMapping_ProcessDiagram(diagrams[i], depth);
    }
}

function SAFMapping_ProcessDiagram(diagram, depth) {
    if (diagram == null) {
        return;
    }
    if (depth == null) {
        depth = 0;
    }

    var diagramKey = "" + diagram.DiagramID;
    if (safProcessedDiagramIds[diagramKey]) {
        return;
    }
    safProcessedDiagramIds[diagramKey] = true;
    safStats.diagrams++;

    SAFMapping_WriteDryRunHierarchyObject(
        depth,
        "Diagram",
        SAFMapping_SafeName(diagram.Name, "<unnamed diagram>"));

    SAFMapping_ChangeDiagramAppliedMetamodel(diagram, depth);
}

function SAFMapping_GetSortedCollection(collection) {
    var result = [];

    if (collection == null) {
        return result;
    }

    for (var i = 0; i < collection.Count; i++) {
        result.push(collection.GetAt(i));
    }

    result.sort(function(a, b) {
        var first = SAFMapping_GetObjectSortKey(a);
        var second = SAFMapping_GetObjectSortKey(b);

        if (first < second) {
            return -1;
        }
        if (first > second) {
            return 1;
        }
        return 0;
    });

    return result;
}

function SAFMapping_GetMergedSortedElementChildren(element) {
    var result = [];
    var seen = {};
    var first = SAFMapping_GetSortedCollection(element.Elements);
    var second = SAFMapping_GetSortedCollection(element.EmbeddedElements);
    var i;

    for (i = 0; i < first.length; i++) {
        if (!seen["" + first[i].ElementID]) {
            seen["" + first[i].ElementID] = true;
            result.push(first[i]);
        }
    }

    for (i = 0; i < second.length; i++) {
        if (!seen["" + second[i].ElementID]) {
            seen["" + second[i].ElementID] = true;
            result.push(second[i]);
        }
    }

    result.sort(function(a, b) {
        var firstKey = SAFMapping_GetObjectSortKey(a);
        var secondKey = SAFMapping_GetObjectSortKey(b);

        if (firstKey < secondKey) {
            return -1;
        }
        if (firstKey > secondKey) {
            return 1;
        }
        return 0;
    });

    return result;
}

function SAFMapping_GetObjectSortKey(object) {
    var name = "";
    var guid = "";

    try {
        name = SAFMapping_Lower(SAFMapping_NormalizeDisplayText(object.Name));
    } catch (e1) {
        name = "";
    }

    try { guid = SAFMapping_SafeString(object.PackageGUID); } catch (e2) { guid = ""; }
    if (guid == "") { try { guid = SAFMapping_SafeString(object.ElementGUID); } catch (e3) { guid = ""; } }
    if (guid == "") { try { guid = SAFMapping_SafeString(object.ConnectorGUID); } catch (e4) { guid = ""; } }
    if (guid == "") { try { guid = SAFMapping_SafeString(object.DiagramGUID); } catch (e5) { guid = ""; } }

    return name + "|" + SAFMapping_Lower(guid);
}

function SAFMapping_ChangePackageName(pkg, depth) {
    var beforeValue = SAFMapping_SafeString(pkg.Name);
    var mapping = SAFMapping_FindMapping(safMappings.packageName, beforeValue);

    if (mapping == null) {
        return;
    }

    SAFMapping_RecordPlannedChange(
        "package",
        pkg.PackageGUID,
        beforeValue,
        beforeValue,
        mapping.toValue,
        depth,
        "Name");
}

function SAFMapping_ChangeElementStereotype(element, depth) {
    var beforeValue = SAFMapping_SafeString(element.StereotypeEx);
    var afterValue = SAFMapping_ApplyStereotypeMappings(beforeValue, safMappings.element);

    if (beforeValue == afterValue) {
        return;
    }

    SAFMapping_RecordPlannedChange(
        "element",
        element.ElementGUID,
        SAFMapping_SafeName(element.Name, "<unnamed element>"),
        beforeValue,
        afterValue,
        depth,
        "Stereotype");
}

function SAFMapping_ChangeConnectorStereotype(connector, depth) {
    var beforeValue = SAFMapping_SafeString(connector.StereotypeEx);
    var afterValue = SAFMapping_ApplyStereotypeMappings(beforeValue, safMappings.connector);

    if (beforeValue == afterValue) {
        return;
    }

    SAFMapping_RecordPlannedChange(
        "connector",
        connector.ConnectorGUID,
        SAFMapping_GetConnectorDisplayName(connector),
        beforeValue,
        afterValue,
        depth,
        "Stereotype");
}
function SAFMapping_ChangeDiagramAppliedMetamodel(diagram, depth) {
    var beforeView = SAFMapping_GetStyleExValue(SAFMapping_SafeString(diagram.StyleEx), "MDGView");
    var mapping = SAFMapping_FindMapping(safMappings.diagramView, beforeView);

    if (mapping == null || beforeView == mapping.toValue) {
        return;
    }

    SAFMapping_RecordPlannedChange(
        "diagramView",
        diagram.DiagramGUID,
        SAFMapping_SafeName(diagram.Name, "<unnamed diagram>"),
        beforeView,
        mapping.toValue,
        depth,
        "Applied Metamodel");
}

function SAFMapping_RecordPlannedChange(kind, guid, name, beforeValue, afterValue, depth, propertyName) {
    var normalizedGuid = SAFMapping_Trim(guid);
    var key = kind + "|" + SAFMapping_Lower(normalizedGuid);

    if (normalizedGuid == "") {
        safStats.errors++;
        SAFMapping_RecordApplyIssue(
            "EMPTY GUID",
            kind,
            normalizedGuid,
            name,
            "Planned change was ignored.");
        return;
    }

    if (safPlannedChangeKeys[key]) {
        var existing = safPlannedChangeKeys[key];

        if (!SAFMapping_ValuesEquivalent(kind, existing.beforeValue, beforeValue) ||
            !SAFMapping_ValuesEquivalent(kind, existing.afterValue, afterValue)) {
            safStats.errors++;
            SAFMapping_RecordApplyIssue(
                "DUPLICATE PLAN CONFLICT",
                kind,
                normalizedGuid,
                name,
                "Existing before='" + existing.beforeValue + "', after='" + existing.afterValue +
                "'; duplicate before='" + beforeValue + "', after='" + afterValue + "'.");
        }
        return;
    }

    var entry = {
        kind: kind,
        guid: normalizedGuid,
        name: SAFMapping_NormalizeDisplayText(name),
        beforeValue: SAFMapping_SafeString(beforeValue),
        afterValue: SAFMapping_SafeString(afterValue),
        depth: depth,
        propertyName: propertyName
    };

    safPlannedChangeKeys[key] = entry;
    safPlannedChanges.push(entry);

    if (kind == "package") {
        safStats.packageDetected++;
    } else if (kind == "element") {
        safStats.elementDetected++;
    } else if (kind == "connector") {
        safStats.connectorDetected++;
    } else if (kind == "diagramView") {
        safStats.diagramViewDetected++;
    }

    SAFMapping_LogChange(
        SAFMapping_GetDisplayKind(kind),
        entry.name,
        entry.guid,
        entry.beforeValue,
        entry.afterValue);

    SAFMapping_WriteDryRunPropertyChange(
        depth + 1,
        propertyName,
        entry.beforeValue,
        entry.afterValue,
        entry.guid);
}

function SAFMapping_FindMapping(collection, currentValue) {
    for (var i = 0; i < collection.length; i++) {
        if (SAFMapping_SameNameOrLocalName(currentValue, collection[i].fromValue)) {
            return collection[i];
        }
    }
    return null;
}

function SAFMapping_ApplyStereotypeMappings(stereotypeList, mappings) {
    var originalValue = SAFMapping_SafeString(stereotypeList);
    var originalParts = SAFMapping_SplitStereotypeList(originalValue);
    var result = [];
    var changed = false;

    for (var i = 0; i < originalParts.length; i++) {
        var original = SAFMapping_Trim(originalParts[i]);

        if (original == "") {
            continue;
        }

        var mapping = SAFMapping_FindMapping(mappings, original);

        if (mapping == null) {
            SAFMapping_AddStereotypeValueToArray(result, original);
        } else {
            changed = true;
            SAFMapping_AddStereotypeValueToArray(result, mapping.toValue);
        }
    }

    return changed ? result.join(",") : originalValue;
}

function SAFMapping_AddStereotypeValueToArray(target, value) {
    var parts = SAFMapping_SplitStereotypeList(value);

    for (var i = 0; i < parts.length; i++) {
        var current = SAFMapping_Trim(parts[i]);

        if (current != "" && !SAFMapping_ArrayContainsStereo(target, current)) {
            target.push(current);
        }
    }
}

function SAFMapping_StereotypeListContains(currentList, stereotypeName) {
    var parts = SAFMapping_SplitStereotypeList(currentList);

    for (var i = 0; i < parts.length; i++) {
        if (SAFMapping_SameNameOrLocalName(parts[i], stereotypeName)) {
            return true;
        }
    }
    return false;
}

function SAFMapping_SplitStereotypeList(value) {
    value = SAFMapping_SafeString(value);
    return value == "" ? [] : value.split(",");
}

function SAFMapping_ArrayContainsStereo(array, stereotypeName) {
    for (var i = 0; i < array.length; i++) {
        if (SAFMapping_SameNameOrLocalName(array[i], stereotypeName)) {
            return true;
        }
    }
    return false;
}

function SAFMapping_GetCanonicalStereotypeList(value) {
    var parts = SAFMapping_SplitStereotypeList(value);
    var result = [];

    for (var i = 0; i < parts.length; i++) {
        var localName = SAFMapping_Lower(SAFMapping_GetLocalName(SAFMapping_Trim(parts[i])));

        if (localName != "" && !SAFMapping_ArrayContainsText(result, localName)) {
            result.push(localName);
        }
    }

    result.sort();
    return result.join(",");
}

function SAFMapping_StereotypeListsEquivalent(firstValue, secondValue) {
    return SAFMapping_GetCanonicalStereotypeList(firstValue) == SAFMapping_GetCanonicalStereotypeList(secondValue);
}

function SAFMapping_ArrayContainsText(array, value) {
    for (var i = 0; i < array.length; i++) {
        if (array[i] == value) {
            return true;
        }
    }
    return false;
}

function SAFMapping_ValuesEquivalent(kind, firstValue, secondValue) {
    firstValue = SAFMapping_SafeString(firstValue);
    secondValue = SAFMapping_SafeString(secondValue);

    if (kind == "element" || kind == "connector") {
        return SAFMapping_StereotypeListsEquivalent(firstValue, secondValue);
    }

    if (kind == "diagramView") {
        if (SAFMapping_Trim(firstValue) == "" || SAFMapping_Trim(secondValue) == "") {
            return SAFMapping_Trim(firstValue) == SAFMapping_Trim(secondValue);
        }
        return SAFMapping_SameNameOrLocalName(firstValue, secondValue);
    }

    return firstValue == secondValue;
}

function SAFMapping_WriteCompleteRollbackSnapshot() {
    for (var i = 0; i < safPlannedChanges.length; i++) {
        var entry = safPlannedChanges[i];
        SAFMapping_WriteRollbackRow(
            entry.kind,
            entry.guid,
            entry.name,
            entry.beforeValue,
            entry.afterValue);
    }
}

function SAFMapping_ApplyPlannedChanges() {
    SAFMapping_Output("=== Applying immutable change plan ===");

    for (var i = 0; i < safPlannedChanges.length; i++) {
        SAFMapping_ApplyPlannedChange(safPlannedChanges[i], i + 1, safPlannedChanges.length);
    }
}

function SAFMapping_ApplyPlannedChange(entry, position, total) {
    var currentInfo = SAFMapping_ReadCurrentValue(entry.kind, entry.guid);

    if (!currentInfo.found) {
        safStats.errors++;
        safStats.applyObjectsMissing++;
        SAFMapping_RecordApplyIssue(
            "MISSING OBJECT",
            entry.kind,
            entry.guid,
            entry.name,
            "Planned change " + position + " of " + total + " could not be applied.");
        return;
    }

    var currentValue = currentInfo.value;

    if (SAFMapping_ValuesEquivalent(entry.kind, currentValue, entry.afterValue)) {
        safStats.applyAlreadyTarget++;
        SAFMapping_MarkApplyTargetVerified(entry);
        SAFMapping_Output(
            "[APPLY_ALREADY_TARGET] " + SAFMapping_GetDisplayKind(entry.kind) + " | " +
            entry.name + " | " + entry.guid + " | Actual: " + SAFMapping_GetReportValue(currentValue));
        return;
    }

    if (!SAFMapping_ValuesEquivalent(entry.kind, currentValue, entry.beforeValue)) {
        safStats.errors++;
        safStats.applyConflicts++;
        SAFMapping_RecordApplyIssue(
            "SOURCE VALUE CONFLICT",
            entry.kind,
            entry.guid,
            entry.name,
            "Expected before='" + entry.beforeValue + "', actual='" + currentValue +
            "', target='" + entry.afterValue + "'.");
        return;
    }

    var updateResult = SAFMapping_SetObjectValue(entry, currentInfo.object);

    if (!updateResult.success) {
        safStats.errors++;
        safStats.applyUpdateFailures++;
        SAFMapping_RecordApplyIssue(
            "UPDATE FAILED",
            entry.kind,
            entry.guid,
            entry.name,
            updateResult.errorText);
        return;
    }

    safStats.applyExplicitUpdates++;

    var verifiedInfo = SAFMapping_ReadCurrentValue(entry.kind, entry.guid);
    var actualAfter = verifiedInfo.found ? verifiedInfo.value : "<object missing after update>";

	if (!verifiedInfo.found || !SAFMapping_ValuesEquivalent(entry.kind, actualAfter, entry.afterValue)) {
		safPendingApplyVerifications.push(entry);
		safStats.applyPendingVerifications++;

		SAFMapping_Output(
			"[APPLY_PENDING_VERIFICATION] " +
			SAFMapping_GetDisplayKind(entry.kind) +
			" | " +
			entry.name +
			" | " +
			entry.guid +
			" | Expected: " +
			SAFMapping_GetReportValue(entry.afterValue) +
			" | Immediate actual: " +
			SAFMapping_GetReportValue(actualAfter));

		return;
	}

    SAFMapping_MarkApplyTargetVerified(entry);
    SAFMapping_Output(
        "[APPLY_OK] " + SAFMapping_GetDisplayKind(entry.kind) + " | " +
        entry.name + " | " + entry.guid + " | " +
        SAFMapping_GetReportValue(entry.beforeValue) + " --> " + SAFMapping_GetReportValue(actualAfter));
}

function SAFMapping_FinalizePendingApplyVerifications() {
    if (safPendingApplyVerifications.length == 0) {
        return;
    }

    SAFMapping_Output("");
    SAFMapping_Output(
        "=== Final verification of pending apply changes ===");

    for (var i = 0; i < safPendingApplyVerifications.length; i++) {
        var entry = safPendingApplyVerifications[i];
        var currentInfo = SAFMapping_ReadCurrentValue(
            entry.kind,
            entry.guid);

        /*
         * Properties and other embedded elements can still be represented
         * by a stale EA automation object. Refresh the newly retrieved
         * element and read it once again.
         */
        if (currentInfo.found && entry.kind == "element") {
            try {
                currentInfo.object.Refresh();
            } catch (refreshError) {
                SAFMapping_Output(
                    "[WARN] Element refresh during final verification failed. GUID: " +
                    entry.guid +
                    " / " +
                    SAFMapping_GetErrorText(refreshError));
            }

            currentInfo = SAFMapping_ReadCurrentValue(
                entry.kind,
                entry.guid);
        }

        var actualValue =
            currentInfo.found
                ? currentInfo.value
                : "<object missing during final verification>";

        if (
            currentInfo.found &&
            SAFMapping_ValuesEquivalent(
                entry.kind,
                actualValue,
                entry.afterValue)
        ) {
            safStats.applyVerifiedInFinalPass++;

            SAFMapping_MarkApplyTargetVerified(
                entry);

            SAFMapping_Output(
                "[APPLY_OK_FINAL] " +
                SAFMapping_GetDisplayKind(entry.kind) +
                " | " +
                entry.name +
                " | " +
                entry.guid +
                " | Actual: " +
                SAFMapping_GetReportValue(actualValue));
        } else {
            safStats.errors++;
            safStats.applyVerificationFailures++;

            SAFMapping_RecordApplyIssue(
                "FINAL VERIFICATION FAILED",
                entry.kind,
                entry.guid,
                entry.name,
                "Expected after='" +
                entry.afterValue +
                "', final actual='" +
                actualValue +
                "', before='" +
                entry.beforeValue +
                "'.");
        }
    }

    safPendingApplyVerifications = [];
}

function SAFMapping_SetObjectValue(entry, object) {
    try {
        if (entry.kind == "package") {
            object.Name = entry.afterValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }
            return { success: true, errorText: "" };
        }

        if (entry.kind == "element") {
            object.StereotypeEx = entry.afterValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }

            if (SAF_MAPPING_SYNC_ELEMENT_TAGGED_VALUES) {
                SAFMapping_SyncElementTagsFromStereotypeList(object, entry.afterValue);
            }

            object.Refresh();
            return { success: true, errorText: "" };
        }

        if (entry.kind == "connector") {
            object.StereotypeEx = entry.afterValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }
            return { success: true, errorText: "" };
        }

        if (entry.kind == "diagramView") {
            object.StyleEx = SAFMapping_SetStyleExValue(
                SAFMapping_SafeString(object.StyleEx),
                "MDGView",
                entry.afterValue);

            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }

            Repository.ReloadDiagram(object.DiagramID);
            return { success: true, errorText: "" };
        }

        return { success: false, errorText: "Unsupported planned change kind: " + entry.kind };
    } catch (e) {
        return { success: false, errorText: SAFMapping_GetErrorText(e) };
    }
}
function SAFMapping_MarkApplyTargetVerified(entry) {
    safStats.applyTargetVerified++;

    if (entry.kind == "package") {
        safStats.packageWritten++;
    } else if (entry.kind == "element") {
        safStats.elementWritten++;
    } else if (entry.kind == "connector") {
        safStats.connectorWritten++;
    } else if (entry.kind == "diagramView") {
        safStats.diagramViewWritten++;
    }
}

function SAFMapping_ReadCurrentValue(kind, guid) {
    try {
        if (kind == "package" || kind == "packageName") {
            var pkg = Repository.GetPackageByGuid(guid);
            return pkg == null
                ? { found: false, object: null, value: "" }
                : { found: true, object: pkg, value: SAFMapping_SafeString(pkg.Name) };
        }

        if (kind == "element") {
            var element = Repository.GetElementByGuid(guid);
            return element == null
                ? { found: false, object: null, value: "" }
                : { found: true, object: element, value: SAFMapping_SafeString(element.StereotypeEx) };
        }

        if (kind == "connector") {
            var connector = Repository.GetConnectorByGuid(guid);
            return connector == null
                ? { found: false, object: null, value: "" }
                : { found: true, object: connector, value: SAFMapping_SafeString(connector.StereotypeEx) };
        }

        if (kind == "diagramView") {
            var diagram = Repository.GetDiagramByGuid(guid);
            return diagram == null
                ? { found: false, object: null, value: "" }
                : {
                    found: true,
                    object: diagram,
                    value: SAFMapping_GetStyleExValue(SAFMapping_SafeString(diagram.StyleEx), "MDGView")
                };
        }
    } catch (e) {
        SAFMapping_Output(
            "[ERROR] Could not read current value. Kind: " + kind + " / GUID: " + guid +
            " / " + SAFMapping_GetErrorText(e));
    }

    return { found: false, object: null, value: "" };
}

function SAFMapping_RecordApplyIssue(issueType, kind, guid, name, details) {
    var issue =
        issueType + " | " + kind + " | " + guid + " | " +
        SAFMapping_NormalizeDisplayText(name);

    if (details != null && SAFMapping_Trim(details) != "") {
        issue += " | " + SAFMapping_NormalizeDisplayText(details);
    }

    safApplyIssues.push(issue);
    SAFMapping_Output("[APPLY DEBUG] " + issue);
}

function SAFMapping_SyncElementTagsFromStereotypeList(element, stereotypeList) {
    var stereotypes = SAFMapping_SplitStereotypeList(stereotypeList);

    for (var i = 0; i < stereotypes.length; i++) {
        var stereotype = SAFMapping_Trim(stereotypes[i]);

        if (stereotype == "") {
            continue;
        }

        var profile = SAFMapping_GetProfileName(stereotype);
        var localName = SAFMapping_GetLocalName(stereotype);

        if (profile == "") {
            continue;
        }

        try {
            element.SynchTaggedValues(profile, localName);
        } catch (e) {
            safStats.errors++;
            SAFMapping_Output(
                "[WARN] Tagged value synchronization failed for element '" + element.Name +
                "' and stereotype '" + stereotype + "': " + SAFMapping_GetErrorText(e));
        }
    }
}

function SAFMapping_OpenDryRunReportWriter(path, defaultMappingPath, projectMappingPath) {
    var fso = new COMObject("Scripting.FileSystemObject");
    SAFMapping_BackupExistingFile(fso, path);

    safDryRunReportWriter = fso.CreateTextFile(path, true, true);
    safDryRunReportWriter.WriteLine("SAF Mapping Dry Run Report");
    safDryRunReportWriter.WriteLine("==========================");
    safDryRunReportWriter.WriteLine("Default mapping: " + defaultMappingPath);
    safDryRunReportWriter.WriteLine(
        projectMappingPath != ""
            ? "Project mapping: " + projectMappingPath
            : "Project mapping: not available");
    safDryRunReportWriter.WriteLine("");
    safDryRunReportWriter.WriteLine("Effective mapping counts");
    safDryRunReportWriter.WriteLine("------------------------");
    safDryRunReportWriter.WriteLine("Packages:   " + safMappings.packageName.length);
    safDryRunReportWriter.WriteLine("Elements:   " + safMappings.element.length);
    safDryRunReportWriter.WriteLine("Connectors: " + safMappings.connector.length);
    safDryRunReportWriter.WriteLine("Diagrams:   " + safMappings.diagramView.length);
    safDryRunReportWriter.WriteLine("");
}

function SAFMapping_CloseDryRunReportWriter() {
    if (safDryRunReportWriter == null) {
        return;
    }

    try {
        SAFMapping_WriteBufferedDryRunHierarchy();
        safDryRunReportWriter.WriteLine("");
        safDryRunReportWriter.WriteLine("Summary");
        safDryRunReportWriter.WriteLine("-------");
        safDryRunReportWriter.WriteLine("Packages scanned:           " + safStats.packages);
        safDryRunReportWriter.WriteLine("Elements scanned:           " + safStats.elements);
        safDryRunReportWriter.WriteLine("Connectors scanned:         " + safStats.connectors);
        safDryRunReportWriter.WriteLine("Diagrams scanned:           " + safStats.diagrams);
        safDryRunReportWriter.WriteLine("Package changes detected:   " + safStats.packageDetected);
        safDryRunReportWriter.WriteLine("Element changes detected:   " + safStats.elementDetected);
        safDryRunReportWriter.WriteLine("Connector changes detected: " + safStats.connectorDetected);
        safDryRunReportWriter.WriteLine("Viewpoint changes detected: " + safStats.diagramViewDetected);
        safDryRunReportWriter.WriteLine("Planned changes:            " + safStats.plannedChanges);
        safDryRunReportWriter.WriteLine("Project overrides:          " + safStats.projectMappingsOverridden);
        safDryRunReportWriter.WriteLine("Errors:                     " + safStats.errors);
        safDryRunReportWriter.Close();
    } catch (e) {
        SAFMapping_Output(
            "[WARN] Dry Run report could not be closed: " + SAFMapping_GetErrorText(e));
    }

    safDryRunReportWriter = null;
}

function SAFMapping_WriteDryRunText(text) {
    if (safMappingMode == SAF_MAPPING_MODE_DRY_RUN && safDryRunReportWriter != null) {
        safDryRunReportWriter.WriteLine(text);
    }
}

function SAFMapping_WriteDryRunHierarchyObject(depth, objectType, objectName) {
    if (safMappingMode != SAF_MAPPING_MODE_DRY_RUN) {
        return;
    }

    var node = {
        depth: depth,
        objectType: objectType,
        objectName: SAFMapping_NormalizeDisplayText(objectName),
        changed: false,
        propertyLines: []
    };

    safDryRunHierarchyNodes.push(node);
    safDryRunHierarchyStack[depth] = node;
    safDryRunHierarchyStack.length = depth + 1;
}

function SAFMapping_WriteDryRunPropertyChange(depth, propertyName, beforeValue, afterValue, guid) {
    if (safMappingMode != SAF_MAPPING_MODE_DRY_RUN) {
        return;
    }

    var objectDepth = depth - 1;
    if (objectDepth < 0) {
        return;
    }

    var node = safDryRunHierarchyStack[objectDepth];
    if (node == null) {
        SAFMapping_Output(
            "[WARN] Dry Run hierarchy node missing for change " + guid +
            " at depth " + objectDepth + ".");
        return;
    }

    var indent = SAFMapping_GetIndent(depth);
    node.propertyLines.push(
        indent + propertyName + ": " + SAFMapping_GetReportValue(beforeValue) +
        " --> " + SAFMapping_GetReportValue(afterValue));
    node.propertyLines.push(indent + "GUID: " + guid);

    for (var i = 0; i <= objectDepth; i++) {
        if (safDryRunHierarchyStack[i] != null) {
            safDryRunHierarchyStack[i].changed = true;
        }
    }
}

function SAFMapping_WriteBufferedDryRunHierarchy() {
    if (safMappingMode != SAF_MAPPING_MODE_DRY_RUN || safDryRunReportWriter == null) {
        return;
    }

    for (var i = 0; i < safDryRunHierarchyNodes.length; i++) {
        var node = safDryRunHierarchyNodes[i];

        if (!node.changed) {
            continue;
        }

        safDryRunReportWriter.WriteLine(
            SAFMapping_GetIndent(node.depth) + "[" + node.objectType + "] " + node.objectName);

        for (var j = 0; j < node.propertyLines.length; j++) {
            safDryRunReportWriter.WriteLine(node.propertyLines[j]);
        }
    }
}

function SAFMapping_GetReportValue(value) {
    value = SAFMapping_SafeString(value);
    return value == "" ? "<empty>" : SAFMapping_NormalizeDisplayText(value);
}

function SAFMapping_GetIndent(depth) {
    var result = "";
    for (var i = 0; i < depth; i++) {
        result += "  ";
    }
    return result;
}

function SAFMapping_OpenRollbackWriter(path) {
    var fso = new COMObject("Scripting.FileSystemObject");
    SAFMapping_BackupExistingFile(fso, path);
    safRollbackWriter = fso.CreateTextFile(path, true, false);
    safRollbackWriter.WriteLine("kind;guid;name;before;after");
}

function SAFMapping_CloseRollbackWriter() {
    if (safRollbackWriter == null) {
        return;
    }

    try {
        safRollbackWriter.Close();
    } catch (e) {
        SAFMapping_Output(
            "[WARN] Rollback file could not be closed: " + SAFMapping_GetErrorText(e));
    }

    safRollbackWriter = null;
}

function SAFMapping_WriteRollbackRow(kind, guid, name, beforeValue, afterValue) {
    if (safRollbackWriter == null) {
        safStats.errors++;
        SAFMapping_Output(
            "[ERROR] Rollback row could not be written because the rollback writer is not open. " +
            "Kind: " + kind + " / GUID: " + guid);
        return false;
    }

    var normalizedName = SAFMapping_NormalizeDisplayText(name);
    var normalizedGuid = SAFMapping_Trim(guid);

    if (normalizedGuid == "") {
        safStats.errors++;
        SAFMapping_Output(
            "[ERROR] Rollback row not written because GUID is empty. Kind: " +
            kind + " / Name: " + normalizedName);
        return false;
    }

    var row =
        SAFMapping_CsvEscape(kind) + SAF_MAPPING_CSV_DELIMITER +
        SAFMapping_CsvEscape(normalizedGuid) + SAF_MAPPING_CSV_DELIMITER +
        SAFMapping_CsvEscape(normalizedName) + SAF_MAPPING_CSV_DELIMITER +
        SAFMapping_CsvEscape(beforeValue) + SAF_MAPPING_CSV_DELIMITER +
        SAFMapping_CsvEscape(afterValue);

    try {
        safRollbackWriter.WriteLine(row);
        safStats.rollbackRowsWritten++;
        return true;
    } catch (e) {
        safStats.errors++;
        SAFMapping_Output(
            "[ERROR] Rollback row write failed. Kind: " + kind + " / GUID: " + normalizedGuid +
            " / Name: " + normalizedName + " / " + SAFMapping_GetErrorText(e));
        return false;
    }
}

function SAFMapping_ApplyRollbackFile(path) {
    var fso = new COMObject("Scripting.FileSystemObject");
    var file = fso.OpenTextFile(path, 1, false);
    var text = file.ReadAll();
    file.Close();

    text = SAFMapping_RemoveBom(text);
    var rows = SAFMapping_ParseCsvText(text, SAFMapping_DetectDelimiterFromText(text));
    var headerProcessed = false;

    for (var i = 0; i < rows.length; i++) {
        var fields = rows[i];

        if (fields == null || fields.length == 0) {
            continue;
        }

        if (fields.length == 1 && SAFMapping_Trim(fields[0]) == "") {
            continue;
        }

        var rawKind = SAFMapping_Trim(fields[0]);

        if (rawKind == "" || SAFMapping_StartsWith(rawKind, "#") || SAFMapping_StartsWith(rawKind, "//")) {
            continue;
        }

        if (!headerProcessed && SAFMapping_Lower(rawKind) == "kind") {
            headerProcessed = true;
            continue;
        }

        headerProcessed = true;

        if (fields.length < 5) {
            safStats.errors++;
            safStats.rollbackRowsSkipped++;
            SAFMapping_Output(
                "[WARN] Ignored rollback row " + (i + 1) +
                ": expected 5 columns, found " + fields.length + ".");
            continue;
        }

        var entry = {
            kind: SAFMapping_NormalizeRollbackKind(rawKind),
            guid: SAFMapping_Trim(fields[1]),
            name: fields[2],
            beforeValue: fields[3],
            afterValue: fields[4]
        };

        if (entry.guid == "") {
            safStats.errors++;
            safStats.rollbackRowsSkipped++;
            SAFMapping_Output(
                "[WARN] Ignored rollback row " + (i + 1) + ": GUID is empty.");
            continue;
        }

        safStats.rollbackRowsRead++;
        SAFMapping_ApplyRollbackEntry(entry, i + 1);
    }
}
function SAFMapping_ApplyRollbackEntry(entry, rowNumber) {
    if (entry.kind != "package" && entry.kind != "element" &&
        entry.kind != "connector" && entry.kind != "diagramView") {
        safStats.errors++;
        safStats.rollbackRowsSkipped++;
        SAFMapping_RecordRollbackIssue(
            "UNKNOWN KIND",
            entry.kind,
            entry.guid,
            entry.name,
            "Rollback row " + rowNumber + " was not applied.");
        return;
    }

    var currentInfo = SAFMapping_ReadCurrentValue(entry.kind, entry.guid);

    if (!currentInfo.found) {
        safStats.errors++;
        SAFMapping_IncrementRollbackMissing(entry.kind);
        SAFMapping_RecordRollbackIssue(
            "MISSING OBJECT",
            entry.kind,
            entry.guid,
            entry.name,
            "Rollback row " + rowNumber + " could not be resolved by GUID.");
        return;
    }

    var currentValue = currentInfo.value;

    if (SAFMapping_ValuesEquivalent(entry.kind, currentValue, entry.beforeValue)) {
        safStats.rollbackRowsAlreadyRestored++;
        safStats.rollbackRowsRestored++;
        SAFMapping_Output(
            "[ROLLBACK_ALREADY_RESTORED] " + SAFMapping_GetDisplayKind(entry.kind) + " | " +
            SAFMapping_NormalizeDisplayText(entry.name) + " | " + entry.guid +
            " | Actual: " + SAFMapping_GetReportValue(currentValue));
        return;
    }

    if (!SAFMapping_ValuesEquivalent(entry.kind, currentValue, entry.afterValue)) {
        safStats.rollbackValueMismatches++;
        SAFMapping_RecordRollbackIssue(
            "CURRENT VALUE MISMATCH",
            entry.kind,
            entry.guid,
            entry.name,
            "Current='" + currentValue + "', expected after='" + entry.afterValue +
            "', restoring before='" + entry.beforeValue + "'.");
    }

    var result = SAFMapping_SetRollbackValue(entry, currentInfo.object);

    if (!result.success) {
        safStats.errors++;
        SAFMapping_RecordRollbackIssue(
            "UPDATE FAILED",
            entry.kind,
            entry.guid,
            entry.name,
            result.errorText);
        return;
    }

    safStats.rollbackRowsApplied++;

    var verifiedInfo = SAFMapping_ReadCurrentValue(entry.kind, entry.guid);
    var actualAfterRollback = verifiedInfo.found ? verifiedInfo.value : "<object missing after rollback>";

    if (!verifiedInfo.found ||
		!SAFMapping_ValuesEquivalent(entry.kind, actualAfterRollback, entry.beforeValue)) {

		safPendingRollbackVerifications.push(entry);
		safStats.rollbackPendingVerifications++;

		SAFMapping_Output(
			"[ROLLBACK_PENDING_VERIFICATION] " +
			SAFMapping_GetDisplayKind(entry.kind) +
			" | " +
			SAFMapping_NormalizeDisplayText(entry.name) +
			" | " +
			entry.guid +
			" | Expected restored: " +
			SAFMapping_GetReportValue(entry.beforeValue) +
			" | Immediate actual: " +
			SAFMapping_GetReportValue(actualAfterRollback));

		return;
	}

    safStats.rollbackRowsRestored++;
    SAFMapping_Output(
        "[ROLLBACK_OK] " + SAFMapping_GetDisplayKind(entry.kind) + " | " +
        SAFMapping_NormalizeDisplayText(entry.name) + " | " + entry.guid + " | " +
        SAFMapping_GetReportValue(currentValue) + " --> " + SAFMapping_GetReportValue(actualAfterRollback));
}

/**
 * Rechecks rollback updates that EA did not expose immediately.
 * Only persistent mismatches are counted as actual rollback failures.
 */
function SAFMapping_FinalizePendingRollbackVerifications() {
    if (safPendingRollbackVerifications.length == 0) {
        return;
    }

    SAFMapping_Output("");
    SAFMapping_Output(
        "=== Final verification of pending rollback changes ===");

    for (var i = 0; i < safPendingRollbackVerifications.length; i++) {
        var entry = safPendingRollbackVerifications[i];
        var currentInfo = SAFMapping_ReadCurrentValue(
            entry.kind,
            entry.guid);

        /*
         * Embedded properties can still be represented by a stale
         * EA automation object. Refresh the newly retrieved element
         * and then resolve it again by GUID.
         */
        if (currentInfo.found && entry.kind == "element") {
            try {
                currentInfo.object.Refresh();
            } catch (refreshError) {
                SAFMapping_Output(
                    "[WARN] Element refresh during final rollback verification failed. GUID: " +
                    entry.guid +
                    " / " +
                    SAFMapping_GetErrorText(refreshError));
            }

            currentInfo = SAFMapping_ReadCurrentValue(
                entry.kind,
                entry.guid);
        }

        var actualValue =
            currentInfo.found
                ? currentInfo.value
                : "<object missing during final rollback verification>";

        if (currentInfo.found &&
            SAFMapping_ValuesEquivalent(
                entry.kind,
                actualValue,
                entry.beforeValue)) {

            safStats.rollbackVerifiedInFinalPass++;
            safStats.rollbackRowsRestored++;

            SAFMapping_Output(
                "[ROLLBACK_OK_FINAL] " +
                SAFMapping_GetDisplayKind(entry.kind) +
                " | " +
                SAFMapping_NormalizeDisplayText(entry.name) +
                " | " +
                entry.guid +
                " | Actual: " +
                SAFMapping_GetReportValue(actualValue));
        } else {
            safStats.errors++;
            safStats.rollbackVerificationFailures++;

            SAFMapping_RecordRollbackIssue(
                "FINAL VERIFICATION FAILED",
                entry.kind,
                entry.guid,
                entry.name,
                "Expected restored='" +
                entry.beforeValue +
                "', final actual='" +
                actualValue +
                "', previous value='" +
                entry.afterValue +
                "'.");
        }
    }

    safPendingRollbackVerifications = [];
}

function SAFMapping_SetRollbackValue(entry, object) {
    try {
        if (entry.kind == "package") {
            object.Name = entry.beforeValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }
            Repository.RefreshModelView(object.PackageID);
            return { success: true, errorText: "" };
        }

        if (entry.kind == "element") {
            object.StereotypeEx = entry.beforeValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }

            if (SAF_MAPPING_SYNC_ELEMENT_TAGGED_VALUES) {
                SAFMapping_SyncElementTagsFromStereotypeList(object, entry.beforeValue);
            }

            object.Refresh();
            return { success: true, errorText: "" };
        }

        if (entry.kind == "connector") {
            object.StereotypeEx = entry.beforeValue;
            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }
            return { success: true, errorText: "" };
        }

        if (entry.kind == "diagramView") {
            object.StyleEx = SAFMapping_SetStyleExValue(
                SAFMapping_SafeString(object.StyleEx),
                "MDGView",
                entry.beforeValue);

            if (!object.Update()) {
                return { success: false, errorText: object.GetLastError() };
            }

            Repository.ReloadDiagram(object.DiagramID);
            return { success: true, errorText: "" };
        }

        return { success: false, errorText: "Unsupported rollback kind: " + entry.kind };
    } catch (e) {
        return { success: false, errorText: SAFMapping_GetErrorText(e) };
    }
}

function SAFMapping_IncrementRollbackMissing(kind) {
    if (kind == "package") {
        safStats.rollbackPackagesMissing++;
    } else if (kind == "element") {
        safStats.rollbackElementsMissing++;
    } else if (kind == "connector") {
        safStats.rollbackConnectorsMissing++;
    } else if (kind == "diagramView") {
        safStats.rollbackDiagramsMissing++;
    }
}

function SAFMapping_RecordRollbackIssue(issueType, kind, guid, name, details) {
    var issue =
        issueType + " | " + kind + " | " + guid + " | " +
        SAFMapping_NormalizeDisplayText(name);

    if (details != null && SAFMapping_Trim(details) != "") {
        issue += " | " + SAFMapping_NormalizeDisplayText(details);
    }

    safRollbackIssues.push(issue);
    SAFMapping_Output("[ROLLBACK DEBUG] " + issue);
}

function SAFMapping_GetStyleExValue(styleEx, key) {
    var entries = SAFMapping_SplitStyleEx(styleEx);
    var normalizedKey = SAFMapping_Lower(SAFMapping_Trim(key));

    for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        var separatorIndex = entry.indexOf("=");

        if (separatorIndex < 0) {
            continue;
        }

        var entryKey = SAFMapping_Trim(entry.substring(0, separatorIndex));
        var entryValue = SAFMapping_Trim(entry.substring(separatorIndex + 1));

        if (SAFMapping_Lower(entryKey) == normalizedKey) {
            return entryValue;
        }
    }

    return "";
}

function SAFMapping_SetStyleExValue(styleEx, key, value) {
    var entries = SAFMapping_SplitStyleEx(styleEx);
    var normalizedKey = SAFMapping_Lower(SAFMapping_Trim(key));
    var result = [];
    var written = false;

    for (var i = 0; i < entries.length; i++) {
        var entry = SAFMapping_Trim(entries[i]);

        if (entry == "") {
            continue;
        }

        var separatorIndex = entry.indexOf("=");

        if (separatorIndex < 0) {
            result.push(entry);
            continue;
        }

        var entryKey = SAFMapping_Trim(entry.substring(0, separatorIndex));

        if (SAFMapping_Lower(entryKey) == normalizedKey) {
            if (!written) {
                result.push(key + "=" + value);
                written = true;
            }
        } else {
            result.push(entry);
        }
    }

    if (!written) {
        result.push(key + "=" + value);
    }

    return result.join(";") + ";";
}

function SAFMapping_SplitStyleEx(styleEx) {
    styleEx = SAFMapping_SafeString(styleEx);
    return styleEx == "" ? [] : styleEx.split(";");
}

function SAFMapping_NormalizeKind(kind) {
    kind = SAFMapping_Lower(SAFMapping_Trim(kind));

    if (kind == "package" || kind == "packagename" || kind == "package_name" ||
        kind == "package-renaming" || kind == "package_renaming") {
        return "packageName";
    }

    if (kind == "element" || kind == "stereotype" || kind == "elementstereotype" ||
        kind == "element_stereotype") {
        return "element";
    }

    if (kind == "connector" || kind == "connectorstereotype" || kind == "connector_stereotype") {
        return "connector";
    }

    if (kind == "diagram" || kind == "diagramview" || kind == "diagram_view" ||
        kind == "diagramtype" || kind == "diagram_type" || kind == "viewpoint" ||
        kind == "viewpointspecification" || kind == "viewpoint_specification" ||
        kind == "appliedmetamodel" || kind == "applied_metamodel" || kind == "mdgview") {
        return "diagramView";
    }

    return kind;
}

function SAFMapping_NormalizeRollbackKind(kind) {
    kind = SAFMapping_Lower(SAFMapping_Trim(kind));

    if (kind == "package" || kind == "packagename" || kind == "package_name") {
        return "package";
    }
    if (kind == "element") {
        return "element";
    }
    if (kind == "connector") {
        return "connector";
    }
    if (kind == "diagram" || kind == "diagramview" || kind == "diagram_view" ||
        kind == "viewpoint" || kind == "mdgview") {
        return "diagramView";
    }
    return kind;
}

function SAFMapping_GetRequiredPathNextToModel(fileName) {
    var path = SAFMapping_GetPathNextToModelWithoutExistenceCheck(fileName);
    var fso = new COMObject("Scripting.FileSystemObject");

    if (!fso.FileExists(path)) {
        throw new Error("Required file not found beside the model: " + path);
    }

    return path;
}

function SAFMapping_GetOptionalPathNextToModel(fileName) {
    var path = SAFMapping_GetPathNextToModelWithoutExistenceCheck(fileName);
    var fso = new COMObject("Scripting.FileSystemObject");
    return fso.FileExists(path) ? path : "";
}

function SAFMapping_GetPathNextToModelWithoutExistenceCheck(fileName) {
    var fso = new COMObject("Scripting.FileSystemObject");
    var modelPath = Repository.ConnectionString;

    if (modelPath == null || SAFMapping_Trim(modelPath) == "") {
        throw new Error(
            "The model path could not be determined from Repository.ConnectionString.");
    }

    if (!fso.FileExists(modelPath)) {
        throw new Error(
            "Repository.ConnectionString is not a file path. The script expects a file-based EA repository. " +
            "ConnectionString: " + modelPath);
    }

    return fso.BuildPath(fso.GetParentFolderName(modelPath), fileName);
}
function SAFMapping_BackupExistingFile(fso, path) {
    if (!fso.FileExists(path)) {
        return;
    }

    var backupPath = path + "." + SAFMapping_GetTimestampForFileName() + ".bak";
    fso.CopyFile(path, backupPath, true);
    SAFMapping_Output("Existing file backed up: " + backupPath);
}

function SAFMapping_DetectDelimiterFromText(text) {
    var firstRecord = "";
    var inQuotes = false;

    for (var i = 0; i < text.length; i++) {
        var character = text.charAt(i);

        if (character == '"') {
            if (inQuotes && i + 1 < text.length && text.charAt(i + 1) == '"') {
                firstRecord += '""';
                i++;
            } else {
                inQuotes = !inQuotes;
                firstRecord += character;
            }
            continue;
        }

        if ((character == "\r" || character == "\n") && !inQuotes) {
            break;
        }

        firstRecord += character;
    }

    var semicolonCount = SAFMapping_CountCharOutsideQuotes(firstRecord, ";");
    var commaCount = SAFMapping_CountCharOutsideQuotes(firstRecord, ",");
    return semicolonCount >= commaCount ? ";" : ",";
}

function SAFMapping_ParseCsvText(text, delimiter) {
    var rows = [];
    var row = [];
    var field = "";
    var inQuotes = false;

    for (var i = 0; i < text.length; i++) {
        var character = text.charAt(i);

        if (character == '"') {
            if (inQuotes && i + 1 < text.length && text.charAt(i + 1) == '"') {
                field += '"';
                i++;
            } else {
                inQuotes = !inQuotes;
            }
            continue;
        }

        if (character == delimiter && !inQuotes) {
            row.push(field);
            field = "";
            continue;
        }

        if ((character == "\r" || character == "\n") && !inQuotes) {
            row.push(field);
            field = "";
            rows.push(row);
            row = [];

            if (character == "\r" && i + 1 < text.length && text.charAt(i + 1) == "\n") {
                i++;
            }
            continue;
        }

        field += character;
    }

    if (field != "" || row.length > 0) {
        row.push(field);
        rows.push(row);
    }

    if (inQuotes) {
        SAFMapping_Output("[WARN] CSV file ended inside a quoted field.");
    }

    return rows;
}

function SAFMapping_CsvEscape(value) {
    value = SAFMapping_SafeString(value);

    var requiresQuotes =
        value.indexOf(SAF_MAPPING_CSV_DELIMITER) >= 0 ||
        value.indexOf('"') >= 0 ||
        value.indexOf("\r") >= 0 ||
        value.indexOf("\n") >= 0;

    value = value.replace(/"/g, '""');
    return requiresQuotes ? '"' + value + '"' : value;
}

function SAFMapping_CountCharOutsideQuotes(line, character) {
    var count = 0;
    var inQuotes = false;

    for (var i = 0; i < line.length; i++) {
        var current = line.charAt(i);

        if (current == '"') {
            if (inQuotes && i + 1 < line.length && line.charAt(i + 1) == '"') {
                i++;
            } else {
                inQuotes = !inQuotes;
            }
        } else if (current == character && !inQuotes) {
            count++;
        }
    }

    return count;
}

function SAFMapping_GetConnectorDisplayName(connector) {
    var name = SAFMapping_Trim(connector.Name);
    return (name == "" ? "<unnamed connector>" : name) + " [" + connector.Type + "]";
}

function SAFMapping_GetProfileName(qualifiedName) {
    qualifiedName = SAFMapping_Trim(qualifiedName);
    var separatorIndex = qualifiedName.indexOf("::");
    return separatorIndex < 0 ? "" : qualifiedName.substring(0, separatorIndex);
}

function SAFMapping_GetLocalName(qualifiedName) {
    qualifiedName = SAFMapping_Trim(qualifiedName);
    var separatorIndex = qualifiedName.lastIndexOf("::");
    return separatorIndex < 0
        ? qualifiedName
        : SAFMapping_Trim(qualifiedName.substring(separatorIndex + 2));
}

function SAFMapping_SameNameOrLocalName(firstValue, secondValue) {
    firstValue = SAFMapping_Trim(firstValue);
    secondValue = SAFMapping_Trim(secondValue);

    if (SAFMapping_Lower(firstValue) == SAFMapping_Lower(secondValue)) {
        return true;
    }

    return SAFMapping_Lower(SAFMapping_GetLocalName(firstValue)) ==
        SAFMapping_Lower(SAFMapping_GetLocalName(secondValue));
}

function SAFMapping_SameText(firstValue, secondValue) {
    return SAFMapping_Lower(SAFMapping_Trim(firstValue)) ==
        SAFMapping_Lower(SAFMapping_Trim(secondValue));
}

function SAFMapping_LogChange(kind, name, guid, beforeValue, afterValue) {
    SAFMapping_Output(
        "[" + kind + "] " + SAFMapping_NormalizeDisplayText(name) + " | " + guid + " | " +
        SAFMapping_GetReportValue(beforeValue) + " --> " + SAFMapping_GetReportValue(afterValue));
}

function SAFMapping_WriteSummary() {
    SAFMapping_Output("");
    SAFMapping_Output("=== Summary ===");
    SAFMapping_Output("Default mappings loaded:       " + safStats.defaultMappingsLoaded);
    SAFMapping_Output("Project mappings added:        " + safStats.projectMappingsLoaded);
    SAFMapping_Output("Default mappings overridden:   " + safStats.projectMappingsOverridden);

    if (safMappingMode != SAF_MAPPING_MODE_ROLLBACK) {
        SAFMapping_Output("Packages scanned:              " + safStats.packages);
        SAFMapping_Output("Elements scanned:              " + safStats.elements);
        SAFMapping_Output("Connectors scanned:            " + safStats.connectors);
        SAFMapping_Output("Diagrams scanned:              " + safStats.diagrams);
        SAFMapping_Output("Package changes detected:      " + safStats.packageDetected);
        SAFMapping_Output("Element changes detected:      " + safStats.elementDetected);
        SAFMapping_Output("Connector changes detected:    " + safStats.connectorDetected);
        SAFMapping_Output("Viewpoint changes detected:    " + safStats.diagramViewDetected);
        SAFMapping_Output("Planned changes:               " + safStats.plannedChanges);
    }

    if (safMappingMode == SAF_MAPPING_MODE_APPLY) {
        SAFMapping_Output("Rollback rows written:         " + safStats.rollbackRowsWritten);
        SAFMapping_Output("Explicit updates executed:     " + safStats.applyExplicitUpdates);
        SAFMapping_Output("Already at target:             " + safStats.applyAlreadyTarget);
        SAFMapping_Output("Target values verified:        " + safStats.applyTargetVerified);
        SAFMapping_Output("Package targets verified:      " + safStats.packageWritten);
        SAFMapping_Output("Element targets verified:      " + safStats.elementWritten);
        SAFMapping_Output("Connector targets verified:    " + safStats.connectorWritten);
        SAFMapping_Output("Viewpoint targets verified:    " + safStats.diagramViewWritten);
        SAFMapping_Output("Missing apply objects:         " + safStats.applyObjectsMissing);
        SAFMapping_Output("Source value conflicts:        " + safStats.applyConflicts);
        SAFMapping_Output("Update failures:               " + safStats.applyUpdateFailures);
        SAFMapping_Output("Apply verification failures:   " + safStats.applyVerificationFailures);
		SAFMapping_Output("Immediate checks deferred:     " + safStats.applyPendingVerifications);
		SAFMapping_Output("Verified in final pass:        " + safStats.applyVerifiedInFinalPass);

        var rollbackComplete = safStats.rollbackRowsWritten == safStats.plannedChanges;
        var targetsComplete = safStats.applyTargetVerified == safStats.plannedChanges;

        SAFMapping_Output(
            "Rollback snapshot coverage:    " +
            (rollbackComplete ? "complete" : "INCOMPLETE"));
        SAFMapping_Output(
            "Apply target coverage:         " +
            (targetsComplete ? "complete" : "INCOMPLETE"));

        if (!rollbackComplete || !targetsComplete) {
            SAFMapping_Output(
                "[ERROR] Apply is incomplete. Planned=" + safStats.plannedChanges +
                ", rollback rows=" + safStats.rollbackRowsWritten +
                ", target values verified=" + safStats.applyTargetVerified + ".");
        }

        if (safApplyIssues.length > 0) {
            SAFMapping_Output("");
            SAFMapping_Output("Apply diagnostic issues:");
            for (var i = 0; i < safApplyIssues.length; i++) {
                SAFMapping_Output("- " + safApplyIssues[i]);
            }
        }
    }

    if (safMappingMode == SAF_MAPPING_MODE_ROLLBACK) {
        SAFMapping_Output("Rollback rows read:            		" + safStats.rollbackRowsRead);
        SAFMapping_Output("Rollback updates executed:     		" + safStats.rollbackRowsApplied);
        SAFMapping_Output("Already restored:              		" + safStats.rollbackRowsAlreadyRestored);
        SAFMapping_Output("Rows verified restored:        		" + safStats.rollbackRowsRestored);
        SAFMapping_Output("Rollback rows skipped:         		" + safStats.rollbackRowsSkipped);
        SAFMapping_Output("Missing packages:              		" + safStats.rollbackPackagesMissing);
        SAFMapping_Output("Missing elements:              		" + safStats.rollbackElementsMissing);
        SAFMapping_Output("Missing connectors:            		" + safStats.rollbackConnectorsMissing);
        SAFMapping_Output("Missing diagrams:              		" + safStats.rollbackDiagramsMissing);
        SAFMapping_Output("Current value mismatches:      		" + safStats.rollbackValueMismatches);
        SAFMapping_Output("Rollback verification failures:		" + safStats.rollbackVerificationFailures);
		SAFMapping_Output("Immediate rollback checks deferred:  " + safStats.rollbackPendingVerifications);
		SAFMapping_Output("Verified in rollback final pass:     " + safStats.rollbackVerifiedInFinalPass);
        SAFMapping_Output(
            "Rollback restoration coverage: " +
            (safStats.rollbackRowsRestored == safStats.rollbackRowsRead ? "complete" : "INCOMPLETE"));

        if (safRollbackIssues.length > 0) {
            SAFMapping_Output("");
            SAFMapping_Output("Rollback diagnostic issues:");
            for (var j = 0; j < safRollbackIssues.length; j++) {
                SAFMapping_Output("- " + safRollbackIssues[j]);
            }
        }
    }

    SAFMapping_Output("Errors:                        " + safStats.errors);

    if (safMappingMode == SAF_MAPPING_MODE_DRY_RUN) {
        SAFMapping_Output("");
        SAFMapping_Output("DRY RUN only. No model changes were written.");
        SAFMapping_Output("Dry Run report written: " + safDryRunReportPath);
    } else if (safMappingMode == SAF_MAPPING_MODE_APPLY) {
        SAFMapping_Output("");
        SAFMapping_Output("Rollback file written: " + safRollbackPath);
    }

    SAFMapping_Output("=== SAF Mapping Migration finished ===");
}

function SAFMapping_GetTimestampForFileName() {
    var date = new Date();
    return "" + date.getFullYear() +
        SAFMapping_Pad2(date.getMonth() + 1) +
        SAFMapping_Pad2(date.getDate()) + "_" +
        SAFMapping_Pad2(date.getHours()) +
        SAFMapping_Pad2(date.getMinutes()) +
        SAFMapping_Pad2(date.getSeconds());
}

function SAFMapping_Pad2(value) {
    value = "" + value;
    return value.length < 2 ? "0" + value : value;
}

function SAFMapping_NormalizeDisplayText(value) {
    value = SAFMapping_SafeString(value).replace(/\r\n|\r|\n/g, " ");
    return SAFMapping_Trim(value);
}

function SAFMapping_SafeName(value, fallback) {
    value = SAFMapping_Trim(value);
    return value == "" ? fallback : value;
}

function SAFMapping_SafeString(value) {
    return value == null ? "" : "" + value;
}

function SAFMapping_Trim(value) {
    return SAFMapping_SafeString(value).replace(/^\s+|\s+$/g, "");
}

function SAFMapping_Lower(value) {
    return SAFMapping_SafeString(value).toLowerCase();
}

function SAFMapping_StartsWith(value, prefix) {
    return value.substring(0, prefix.length) == prefix;
}

function SAFMapping_RemoveBom(value) {
    return value.length > 0 && value.charCodeAt(0) == 0xFEFF ? value.substring(1) : value;
}

function SAFMapping_GetErrorText(error) {
    if (error == null) {
        return "";
    }
    if (error.description != null) {
        return error.description;
    }
    if (error.message != null) {
        return error.message;
    }
    return "" + error;
}

function SAFMapping_Output(message) {
    Session.Output(message);
}
